MONEY = ('₽', 'руб', 'ФОТ', 'бюджет', 'ROI', 'деньг', 'стоимост', 'стоит', 'потер', 'оплат', 'смет', 'переплат', 'окуп', 'лицензи', 'токен', 'зарплат', 'ставк', 'ценност', 'затрат', 'дорож')
GAIN = ('%', 'час', 'минут', 'быстр', 'срок', 'дедлайн', 'эффективн', 'производительн', 'продуктивн', 'тимлид', 'найм', 'испытательн', 'бага', 'багов', 'техдолг', 'риск')
OVERRIDE_C = {  # начало тезиса → Ц, ручные поправки эвристики
    'В акте 160 часов': 5, 'Senior с ИИ: +50': 5, 'Оплата — только после': 5, 'Окупается ли ИИ': 5,
    'Резюме можно накрутить': 4, 'Грейд, который подтверждает': 4, 'Цифровой тимлид, который проверяет': 4,
    'Рейтинг разработчиков': 4, 'Тех-мэтч': 3, 'Техдолг в цифрах': 4, 'Результат с первого дня': 4,
    'Тимлид успевает менторить': 4, 'Системные ошибки': 4, 'Авто-детект ИИ-кода': 4, 'Разрыв между самооценкой': 4,
    'Performance review без споров': 4, 'Бесплатный пилот': 5, 'Код, написанный за год': 4,
}

def biz(r):
    """Ц — бизнес-ценность (1–5): насколько тезис говорит о деньгах, времени и рисках бизнеса."""
    text, typ = r[3], r[2]
    for k, v in OVERRIDE_C.items():
        if text.startswith(k):
            return v
    low = text.lower()
    if any(k.lower() in low for k in MONEY):
        return 5 if typ in ('Выгода', 'Решение', 'Заголовок', 'Доказательство') else 4
    if any(k.lower() in low for k in GAIN):
        return 4 if typ in ('Выгода', 'Решение', 'Доказательство', 'Боль', 'Заголовок') else 3
    if typ in ('Безопасность', 'Возражение'):
        return 3
    return 2 if any(k in text for k in ('AST', 'ISO', 'стек', 'язык', 'Интеграц', 'интеграц')) else 3

# Итог = (Б*0.25 + Ц*0.20 + К*0.15 + Д*0.15 + О*0.125 + Я*0.125) * 20
W = {'Б': 0.25, 'Ц': 0.20, 'К': 0.15, 'Д': 0.15, 'О': 0.125, 'Я': 0.125}

def score(b, c, k, d, o, y):
    return round((b * W['Б'] + c * W['Ц'] + k * W['К'] + d * W['Д'] + o * W['О'] + y * W['Я']) * 20)

rows = []
for i, r in enumerate(R + B, 1):
    src, url = S[r[4]]
    c = r[11] if len(r) > 11 else biz(r)
    rows.append({
        'id': i, 'раздел': r[0], 'ЦА': r[1], 'тип': r[2], 'тезис': r[3],
        'источник': src, 'ссылка': url,
        'боль': r[5], 'бизнес-ценность': c, 'конкретика': r[6], 'доказуемость': r[7], 'отличие': r[8], 'ясность': r[9],
        'итог': score(r[5], c, r[6], r[7], r[8], r[9]), 'где в макетах': r[10],
    })
rows.sort(key=lambda x: (-x['итог'], x['раздел']))
for n, x in enumerate(rows, 1):
    x['ранг'] = n

root = os.path.join(os.path.dirname(__file__), '..', '..', 'docs', 'content')
cols = ['ранг', 'итог', 'раздел', 'ЦА', 'тип', 'тезис', 'боль', 'бизнес-ценность', 'конкретика', 'доказуемость', 'отличие', 'ясность', 'источник', 'ссылка', 'где в макетах', 'id']
with open(os.path.join(root, 'theses.csv'), 'w', encoding='utf-8-sig', newline='') as f:
    w = csv.DictWriter(f, fieldnames=cols, delimiter=';')
    w.writeheader(); w.writerows(rows)
with open(os.path.join(root, 'theses.json'), 'w', encoding='utf-8') as f:
    json.dump(rows, f, ensure_ascii=False, indent=0)
with open(os.path.join(root, 'theses.md'), 'w', encoding='utf-8') as f:
    f.write('# Тезисы для сайта UpCore — оценка и рейтинг\n\n')
    f.write('Критерии (1–5): **Б** — острота боли и актуальность для ЦА; **Ц** — бизнес-ценность (деньги, время, риски бизнеса); '
            '**К** — конкретика, цифры; **Д** — доказуемость (подтверждаем продуктом или источником); **О** — отличие от конкурентов; **Я** — ясность за 5 секунд.\n'
            'Итог = (Б×0,25 + Ц×0,20 + К×0,15 + Д×0,15 + О×0,125 + Я×0,125) × 20 → 0–100. Генерируется `tools/content/theses.py`.\n'
            'Тип «Бизнес-показатель» — цифры эффекта; с пометкой «таблица (конкурент)» — ориентир рынка, на сайт не выносим.\n\n')
    f.write('| # | Итог | Раздел | ЦА | Тип | Тезис | Б | Ц | К | Д | О | Я | Источник | Где в макетах |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n')
    for x in rows:
        src = f"[{x['источник']}]({x['ссылка']})" if x['ссылка'] else x['источник']
        f.write(f"| {x['ранг']} | **{x['итог']}** | {x['раздел']} | {x['ЦА']} | {x['тип']} | {x['тезис']} | {x['боль']} | {x['бизнес-ценность']} | {x['конкретика']} | {x['доказуемость']} | {x['отличие']} | {x['ясность']} | {src} | {x['где в макетах']} |\n")
